import React from 'react';

/**
 * Декоративный радиальный градиент-блик.
 * Используется на страницах Auth / Register и др.
 *
 * Props:
 *  - className: дополнительные классы (позиционирование, размеры, поворот)
 */
const GradientBlob = ({ className = '' }) => (
  <div
    aria-hidden
    className={`pointer-events-none ${className}`}
    style={{
      background:
        'radial-gradient(ellipse closest-side at center, #FF6600 0%, #FFCC00 36%, #FF0055 75%, rgba(255, 0, 85, 0) 100%)',
    }}
  />
);

export default GradientBlob;
